(12, '/unminifier', 'Calcify Hub | Unminifier', 'This is a Js/Css Unminifier', '\"{\\\"h-0\\\":\\\"Calcify\\\",\\\"h-1\\\":\\\"Hub\\\",\\\"h-2\\\":\\\"Home\\\",\\\"h-3\\\":\\\"Tools\\\",\\\"h-4\\\":\\\"Estimators\\\",\\\"h-5\\\":\\\"Usage Base Solar\\\",\\\"h-6\\\":\\\"Budget Base Solar\\\",\\\"h-7\\\":\\\"Construction Cost\\\",\\\"h-8\\\":\\\"Formatters & Convertors\\\",\\\"h-9\\\":\\\"Text Formatter\\\",\\\"h-10\\\":\\\"Text Encrypt\\\\\\/Decrypt\\\",\\\"h-11\\\":\\\"Image Converter\\\",\\\"h-12\\\":\\\"Pdf To word\\\",\\\"h-13\\\":\\\"Others\\\",\\\"h-14\\\":\\\"Age Calculator\\\",\\\"h-15\\\":\\\"Tax Calculator\\\",\\\"h-16\\\":\\\"Minify Js\\\\\\/Css\\\",\\\"h-17\\\":\\\"Unminify Js\\\\\\/Css\\\",\\\"h-18\\\":\\\"Compare Data\\\",\\\"h-19\\\":\\\"About Us\\\",\\\"h-20\\\":\\\"Contact Us\\\",\\\"f-0\\\":\\\"Your Daily Utility Hub\\\",\\\"f-1\\\":\\\"Pages\\\",\\\"f-2\\\":\\\"Newsletter\\\",\\\"f-3\\\":\\\"Subscribe to get updates on new tools and features.\\\",\\\"f-4\\\":\\\"Your email\\\",\\\"f-5\\\":\\\"Subscribe\\\",\\\"f-6\\\":\\\"\\\\u00a9 2025 Calcify Hub. All rights reserved.\\\",\\\"f-7\\\":\\\"Privacy Policy\\\",\\\"f-8\\\":\\\"Terms & Conditions\\\"}\"', '2025-07-21 06:32:25', '2025-08-01 01:08:30'),
(13, '/about-us', 'Calcify Hub | About us', 'This is a About Page', '\"{\\\"0\\\":\\\"About\\\",\\\"1\\\":\\\"Us\\\",\\\"2\\\":\\\"Estimate your construction cost based on area, material quality, and labor rates using this accurate and easy calculator.\\\",\\\"3\\\":\\\"Our Story\\\",\\\"4\\\":\\\"Calcify Hub Tools was born out of frustration with having to jump between multiple websites to complete simple development tasks. We envisioned a single platform where developers could access all the essential tools they need in their daily workflow.\\\",\\\"5\\\":\\\"Since our launch in 2023, we\'ve grown from a handful of basic tools to a comprehensive suite serving thousands of developers worldwide. Our mission is to simplify your workflow and boost your productivity.\\\",\\\"6\\\":\\\"What We Offer\\\",\\\"7\\\":\\\"Code Tools\\\",\\\"8\\\":\\\"Encoders, decoders, minifiers, and formatters for all major programming languages and formats including JSON, HTML, CSS, and JavaScript.\\\",\\\"9\\\":\\\"Measurement Tools\\\",\\\"10\\\":\\\"Accurate estimators and calculators to help you plan projects, calculate sizes, and measure performance metrics.\\\",\\\"11\\\":\\\"Quick Utilities\\\",\\\"12\\\":\\\"Essential utilities for everyday tasks including color pickers, regex testers, and data converters.\\\",\\\"13\\\":\\\"Our Principles\\\",\\\"14\\\":\\\"Privacy First\\\",\\\"15\\\":\\\"All processing happens in your browser whenever possible. We don\'t store your data unless you explicitly ask us to.\\\",\\\"16\\\":\\\"Performance\\\",\\\"17\\\":\\\"Our tools are optimized for speed. We know you\'re busy, so we make sure our tools work as fast as you do.Our tools are optimized for speed. We know you\'re busy, so we make sure our tools work as fast as you do.\\\",\\\"18\\\":\\\"Developer Focused\\\",\\\"19\\\":\\\"Built by developers, for developers. We prioritize the tools and features that actually matter in your daily work.\\\",\\\"h-0\\\":\\\"Calcify\\\",\\\"h-1\\\":\\\"Hub\\\",\\\"h-2\\\":\\\"Home\\\",\\\"h-3\\\":\\\"Tools\\\",\\\"h-4\\\":\\\"Estimators\\\",\\\"h-5\\\":\\\"Usage Base Solar\\\",\\\"h-6\\\":\\\"Budget Base Solar\\\",\\\"h-7\\\":\\\"Construction Base\\\",\\\"h-8\\\":\\\"Formatters & Convertors\\\",\\\"h-9\\\":\\\"Text Formatter\\\",\\\"h-10\\\":\\\"Text Encrypt\\\\\\/Decrypt\\\",\\\"h-11\\\":\\\"Image Converter\\\",\\\"h-12\\\":\\\"Pdf To word\\\",\\\"h-13\\\":\\\"Others\\\",\\\"h-14\\\":\\\"Age Calculator\\\",\\\"h-15\\\":\\\"Tax Calculator\\\",\\\"h-16\\\":\\\"Minify Js\\\\\\/Css\\\",\\\"h-17\\\":\\\"Unminify Js\\\\\\/Css\\\",\\\"h-18\\\":\\\"Compare Data\\\",\\\"h-19\\\":\\\"About Us\\\",\\\"h-20\\\":\\\"Contact Us\\\",\\\"f-0\\\":\\\"Your Daily Utility Hub\\\",\\\"f-1\\\":\\\"Pages\\\",\\\"f-2\\\":\\\"Newsletter\\\",\\\"f-3\\\":\\\"Subscribe to get updates on new tools and features.\\\",\\\"f-4\\\":\\\"Your email\\\",\\\"f-5\\\":\\\"Subscribe\\\",\\\"f-6\\\":\\\"\\\\u00a9 2025 Calcify Hub. All rights reserved.\\\",\\\"f-7\\\":\\\"Privacy Policy\\\",\\\"f-8\\\":\\\"Terms & Conditions\\\"}\"', '2025-07-21 06:59:15', '2025-08-01 01:04:31');
