(14, '/contact-us', 'Calcify Hub | Contact us', 'This is a Contact Page', '\"{\\\"0\\\":\\\"Contact\\\",\\\"1\\\":\\\"Us\\\",\\\"2\\\":\\\"Estimate your construction cost based on area, material quality, and labor rates using this accurate and easy calculator.\\\",\\\"3\\\":\\\"Send us a message\\\",\\\"4\\\":\\\"Your Name\\\",\\\"5\\\":\\\"Email Address\\\",\\\"6\\\":\\\"Subject\\\",\\\"7\\\":\\\"Select a Topic\\\",\\\"8\\\":\\\"Feedback\\\\\\/Suggestions\\\",\\\"9\\\":\\\"Report a Bug\\\",\\\"10\\\":\\\"Feature Request\\\",\\\"11\\\":\\\"Business Inquery\\\",\\\"12\\\":\\\"Others\\\",\\\"13\\\":\\\"Message\\\",\\\"14\\\":\\\"Your message here...\\\",\\\"15\\\":\\\"Send Message\\\",\\\"16\\\":\\\"Other ways to reach us\\\",\\\"17\\\":\\\"Email Support\\\",\\\"18\\\":\\\"For general inquiries:\\\",\\\"19\\\":\\\"For business inquiries:\\\",\\\"20\\\":\\\"Community & Social\\\",\\\"21\\\":\\\"Before you contact us\\\",\\\"22\\\":\\\"Check our FAQ page for common questions\\\",\\\"23\\\":\\\"For bug reports, please include steps to reproduce\\\",\\\"24\\\":\\\"Feature requests are welcome - tell us how it would help you\\\",\\\"25\\\":\\\"We typically respond within 1-2 business days\\\",\\\"h-0\\\":\\\"Calcify\\\",\\\"h-1\\\":\\\"Hub\\\",\\\"h-2\\\":\\\"Home\\\",\\\"h-3\\\":\\\"Tools\\\",\\\"h-4\\\":\\\"Estimators\\\",\\\"h-5\\\":\\\"Usage Base Solar\\\",\\\"h-6\\\":\\\"Budget Base Solar\\\",\\\"h-7\\\":\\\"Construction Base\\\",\\\"h-8\\\":\\\"Formatters & Convertors\\\",\\\"h-9\\\":\\\"Text Formatter\\\",\\\"h-10\\\":\\\"Text Encrypt\\\\\\/Decrypt\\\",\\\"h-11\\\":\\\"Image Converter\\\",\\\"h-12\\\":\\\"Pdf To word\\\",\\\"h-13\\\":\\\"Others\\\",\\\"h-14\\\":\\\"Age Calculator\\\",\\\"h-15\\\":\\\"Tax Calculator\\\",\\\"h-16\\\":\\\"Minify Js\\\\\\/Css\\\",\\\"h-17\\\":\\\"Unminify Js\\\\\\/Css\\\",\\\"h-18\\\":\\\"Compare Data\\\",\\\"h-19\\\":\\\"About Us\\\",\\\"h-20\\\":\\\"Contact Us\\\",\\\"f-0\\\":\\\"Your Daily Utility Hub\\\",\\\"f-1\\\":\\\"Pages\\\",\\\"f-2\\\":\\\"Newsletter\\\",\\\"f-3\\\":\\\"Subscribe to get updates on new tools and features.\\\",\\\"f-4\\\":\\\"Your email\\\",\\\"f-5\\\":\\\"Subscribe\\\",\\\"f-6\\\":\\\"\\\\u00a9 2025 Calcify Hub. All rights reserved.\\\",\\\"f-7\\\":\\\"Privacy Policy\\\",\\\"f-8\\\":\\\"Terms & Conditions\\\"}\"', '2025-07-21 07:17:26', '2025-08-01 01:06:19'),
